from pathlib import Path
import subprocess,os,json,datetime
from zoneinfo import ZoneInfo
root=Path('/srv/projects/telegram-robot-leads')
unitname='telegram-leads-activate-20261020'
script=Path('/usr/local/sbin/telegram_leads_activate_20261020.py')
service=Path('/etc/systemd/system/'+unitname+'.service')
timer=Path('/etc/systemd/system/'+unitname+'.timer')
