files={script:dest/script.name,service:dest/service.name,timer:dest/timer.name}
def call(args,t=30):
 return subprocess.run(args,capture_output=True,text=True,timeout=t)
def systemd(n):
 return call(['systemctl','is-active',n+'.service'],9).stdout.strip()
def pm():
 q=call(['pm2','jlist'],16)
 if q.returncode:raise RuntimeError('PM2 unavailable')
 return {x.get('name'):{'pid':x.get('pid'),'status':(x.get('pm2_env') or {}).get('status')} for x in json.loads(q.stdout) if x.get('name') in ('iptvpn_bot','telegram-robot-leads')}
names=['pm2-root','fadego-staging','lowcost-europa','pink-iptv-backend','pink-vpn','nginx','postgresql@16-main']
baseline={n:systemd(n) for n in names}
before=pm()
if any(x!='active' for x in baseline.values()) or any(before.get(x,{}).get('status')!='online' for x in ('iptvpn_bot','telegram-robot-leads')):raise RuntimeError('Protected services not active')
if not root.is_dir() or root.is_symlink() or dest.exists() or dest.is_symlink():raise RuntimeError('Project archive target differs')
for p,new in files.items():
 if not p.is_file() or p.is_symlink() or p.stat().st_uid!=0 or new.exists() or new.is_symlink():raise RuntimeError('Unexpected legacy file: '+str(p))
