if datetime.datetime.now(ZoneInfo('Europe/Lisbon'))<=datetime.datetime(2026,10,20,22,0,tzinfo=ZoneInfo('Europe/Lisbon')):raise RuntimeError('Activation period not expired')
if '/opt/telegram-robot-leads' not in raw or '/root/project-secrets/telegram-robot-leads' not in raw:raise RuntimeError('Old activator differs from examined version')
r=call(['systemctl','show',unitname+'.timer','-p','UnitFileState','-p','ActiveState','--no-pager'],12)
if r.returncode:raise RuntimeError('Cannot inspect current timer')
flags=dict(x.split('=',1) for x in r.stdout.splitlines() if '=' in x)
if flags.get('UnitFileState')!='enabled' or flags.get('ActiveState')!='active':raise RuntimeError('Timer no longer enabled and active')
r=call(['systemctl','is-active',unitname+'.service'],9)
if r.stdout.strip()!='inactive':raise RuntimeError('Unexpected running legacy service')
disabled=False
moved=[]
try:
 r=call(['systemctl','disable','--now',unitname+'.timer'],30)
 if r.returncode:raise RuntimeError('Unable to disable expired timer')
 disabled=True
 dest.mkdir(parents=True,mode=0o700)
 for p,new in files.items():
  inode=p.stat().st_ino
  p.rename(new)
  moved.append((p,new))
  if p.exists() or new.stat().st_ino!=inode:raise RuntimeError('Archived file inode mismatch')
 r=call(['systemctl','daemon-reload'],30)
 if r.returncode:raise RuntimeError('Systemd reload failure')
 r=call(['systemctl','show',unitname+'.timer','-p','ActiveState','--no-pager'],10)
 if 'ActiveState=active' in r.stdout:raise RuntimeError('Expired timer still active')
 if any(systemd(n)!=v for n,v in baseline.items()):raise RuntimeError('Protected systemd service changed')
 if pm()!=before:raise RuntimeError('Telegram bot status/PID changed')
except Exception:
 for p,new in reversed(moved):
  if new.exists() and not p.exists():new.rename(p)
 call(['systemctl','daemon-reload'],28)
 if disabled:call(['systemctl','enable','--now',unitname+'.timer'],30)
 print('ARCHIVE_ROLLBACK=APPLIED')
 raise
print('EXPIRED_ACTIVATOR_ARCHIVED='+str(dest))
